function dailyDay(t){ var d=new Date(t||Date.now()); return d.getFullYear()+'-'+('0'+(d.getMonth()+1)).slice(-2)+'-'+('0'+d.getDate()).slice(-2); }
function dailyLabel(d){ var p=String(d||'').split('-'); return (DAILY_MON[(+p[1]||1)-1]||'')+' '+(+p[2]||0); }
