  L.push({d:today,t:Date.now(),runs:Math.max(0,o.runs|0),cr:Math.round(o.credits)||0,raw:raw});
  L.sort(function(a,b){ return a.d<b.d?-1:(a.d>b.d?1:0); });
  while(L.length>DAILY_BAK.keep) L.shift();
